import{_ as t,o as a,c as s,ak as o}from"./chunks/framework.sV-XtlWr.js";const u=JSON.parse('{"title":"Core concepts","description":"","frontmatter":{"title":"Core concepts","lang":"en-US"},"headers":[],"relativePath":"concepts.md","filePath":"concepts.md","lastUpdated":1785251264000}'),r={name:"concepts.md"};function n(i,e,c,l,d,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core concepts&quot;">​</a></h1><p>Piwi reuses Playwright&#39;s vocabulary where it can, but a dashboard that keeps history needs a few distinctions Playwright doesn&#39;t have to make — most importantly between <em>a test</em> and <em>one run of that test</em>. This page defines the words the rest of the documentation and the UI use.</p><h2 id="the-object-model" tabindex="-1">The object model <a class="header-anchor" href="#the-object-model" aria-label="Permalink to &quot;The object model&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Project                      one test suite you submit results for</span></span>
<span class="line"><span>└── Test run                 one \`npx playwright test\` (all shards merged)</span></span>
<span class="line"><span>    └── Execution            one attempt of one test, on one browser</span></span>
<span class="line"><span>        └── belongs to a Test case   the test&#39;s identity across all runs</span></span>
<span class="line"><span>             │</span></span>
<span class="line"><span>             └── Failure cluster     executions that failed the same way</span></span></code></pre></div><p>Read it in two directions:</p><ul><li><strong>Down</strong> — &quot;what happened in this run?&quot; A run holds executions; each execution points at the test it is an attempt of.</li><li><strong>Across</strong> — &quot;how has this test behaved?&quot; A test case holds every execution of itself, in every run, over time. That&#39;s the axis flakiness, pass rate, and duration trends are computed on.</li></ul><h2 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h2><p>A named container for one suite&#39;s results — usually one repository, or one suite within it. Projects are created automatically the first time results are submitted under a new <code>projectName</code>; you never have to pre-register one.</p><p>A project carries its own tags, retention, access assignments, SCM connection, and AI-diagnosis instructions.</p><h2 id="test-run" tabindex="-1">Test run <a class="header-anchor" href="#test-run" aria-label="Permalink to &quot;Test run&quot;">​</a></h2><p>Everything one <code>npx playwright test</code> invocation produced: counts, duration, the HTML report, CI and git metadata, and every execution inside it.</p><p>Two things commonly surprise people:</p><ul><li><strong>Shards merge into one run.</strong> Ten <code>--shard</code> jobs produce one run, not ten. The reporter derives a stable <em>run label</em> from your CI&#39;s pipeline ID and every shard submits against it; the run stays <code>running</code> until the last shard finishes. See <a href="./ci.html">CI &amp; sharding</a>.</li><li><strong>A run can be watched while it happens.</strong> With streaming enabled (the default), the run row appears when the suite starts and fills in test by test, so a failure is browsable before CI finishes.</li></ul><h2 id="test-case" tabindex="-1">Test case <a class="header-anchor" href="#test-case" aria-label="Permalink to &quot;Test case&quot;">​</a></h2><p>The <strong>identity of a test across time</strong>, keyed by project + file path + <code>describe</code> path + title. It is not a row you submit — it&#39;s created and reused as results arrive, so renaming a test creates a new one and moving a spec file does too.</p><p>A test case is browser-independent: <code>login.spec.ts › signs in</code> is one test case whether it ran on Chromium, Firefox, or all five projects in your matrix.</p><p>This is the object at <code>/test-cases/:id</code> — pass rate, duration trend, status history, and the list of every execution.</p><h2 id="execution" tabindex="-1">Execution <a class="header-anchor" href="#execution" aria-label="Permalink to &quot;Execution&quot;">​</a></h2><p><strong>One attempt of one test case, in one run, on one browser.</strong> Retries are separate executions, not a field on one: a test that failed twice and passed on the third attempt contributes three executions to the same run. So is each browser in a project matrix.</p><p>This is the object at <code>/test-run-cases/:id</code> — the error, steps, trace, screenshots, console, network, Web Vitals, and (for a failure) the diagnosis view. When the docs say <em>execution</em> or <em>test-run case</em>, this is what they mean; when they say <em>test case</em>, they mean the identity above it.</p><p>The distinction matters in practice: &quot;this test is flaky&quot; is a statement about a <strong>test case</strong>, and &quot;here is the stack trace&quot; is a statement about one <strong>execution</strong>.</p><h2 id="error-fingerprint-failure-cluster" tabindex="-1">Error fingerprint &amp; failure cluster <a class="header-anchor" href="#error-fingerprint-failure-cluster" aria-label="Permalink to &quot;Error fingerprint &amp; failure cluster&quot;">​</a></h2><p>When an execution fails, Piwi hashes a normalized form of its error — error type, message with the volatile parts masked out (timeouts, numbers, UUIDs, URLs, expected/received values), and the locator with its dynamic arguments masked. That hash is the <strong>error fingerprint</strong>.</p><p>Every failed execution sharing a fingerprint joins one <strong>failure cluster</strong>. Fifty red tests caused by one broken endpoint become one cluster you triage once, with a status (open / resolved / ignored) and a note.</p><p>Fingerprints deliberately <strong>ignore the failing stack frame</strong>, so the same root cause reached from six different spec files stays one cluster. Full detail: <a href="./ai-diagnosis.html">Failure clustering &amp; AI diagnosis</a>.</p><h2 id="baseline-last-green-run" tabindex="-1">Baseline (last green run) <a class="header-anchor" href="#baseline-last-green-run" aria-label="Permalink to &quot;Baseline (last green run)&quot;">​</a></h2><p>Several views answer &quot;what changed?&quot; — run insights, the regression signals on a test, the environment and visual diffs, and the git diff behind an AI diagnosis. They all compare against a <strong>baseline</strong>: the most recent passing run of the same project (and branch, where relevant).</p><p>Two derived flags are stored per execution:</p><ul><li><strong>New regression</strong> — passed in the baseline, fails now.</li><li><strong>New flaky</strong> — didn&#39;t retry in the baseline, passed on retry now.</li></ul><h2 id="flakiness-score" tabindex="-1">Flakiness score <a class="header-anchor" href="#flakiness-score" aria-label="Permalink to &quot;Flakiness score&quot;">​</a></h2><p>A test case&#39;s <strong>composite score</strong> from three independent signals — retry passes, status alternation across runs, and overall failure rate — plus a <strong>root-cause class</strong> (timing, network, assertion, environment, other) and an <strong>impact ranking</strong> in wasted CI minutes. It&#39;s a property of the test case, computed over its execution history, which is why a test needs a few runs of history before it can be called flaky. See <a href="./flaky-tests.html">Flaky tests</a>.</p><h2 id="locator-snapshot" tabindex="-1">Locator snapshot <a class="header-anchor" href="#locator-snapshot" aria-label="Permalink to &quot;Locator snapshot&quot;">​</a></h2><p>When the <a href="./capture-fixtures.html">capture fixtures</a> are installed, every successful locator call records what the element actually looked like — role, accessible name, test id, structural anchors — keyed by the <strong>call site</strong> (<code>file:line</code>) rather than the selector text. One row per call site, refreshed on each passing run.</p><p>When that locator later fails, those snapshots are what Piwi ranks replacement locators from. See <a href="./reporter.html#locator-healing">Locator healing</a>.</p><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><p>A free-text label on a run (<code>production</code>, <code>staging</code>, a preview URL, whatever you use), set with the reporter&#39;s <code>environment</code> option or <code>PIWI_ENVIRONMENT</code>. It&#39;s a <strong>scoping</strong> dimension, not a configuration one: flaky analysis, analytics, and timeline markers can all be narrowed to a single environment so a staging suite&#39;s noise doesn&#39;t blend into production&#39;s numbers.</p><h2 id="tags-ownership" tabindex="-1">Tags &amp; ownership <a class="header-anchor" href="#tags-ownership" aria-label="Permalink to &quot;Tags &amp; ownership&quot;">​</a></h2><p>Two ways to say what a test <em>is</em>, both declared in the spec file and both read by the reporter.</p><p><strong>Tags</strong> come from Playwright itself — <code>@smoke</code> in a title or the <code>{ tag: [...] }</code> option. Piwi stores them with the leading <code>@</code> stripped, on the execution (what that run saw) and on the test case (the latest declaration). They are how you slice the test-case catalog and the flaky leaderboard, and what the <a href="./ci.html#blocking-a-merge">CI gate</a>&#39;s <code>--require-tag</code> rule matches on.</p><p><strong>Ownership metadata</strong> comes from four <code>piwi:</code> annotations — <code>owner</code>, <code>priority</code>, <code>feature</code> and <code>link</code>. Where a tag groups tests, this says who answers for one. It shows as badges wherever the test is listed and is carried into <a href="./ci.html#pull-request-feedback">pull-request feedback</a>, so a failure comment names the team rather than leaving a reviewer to guess.</p><p>Both are optional and neither changes how a test runs. Details and the exact accepted values are in <a href="./reporter.html#test-tags">Reporter → Test tags</a>.</p><p><strong>When a test declares no owner, Piwi reads your repository&#39;s CODEOWNERS instead.</strong> Asking every team to annotate every test is how ownership features die; the repository already records who owns which files, and Piwi can read it because it runs inside your network with a token it already has. So ownership works on day one with no test edits, and a <code>piwi:owner</code> annotation still wins wherever a team wants to be explicit.</p><p>That derived owner is used in <a href="./ci.html#pull-request-feedback">pull-request comments</a>, on the flaky leaderboard, and by the <code>owners</code> <a href="./notifications.html#subscriptions">notification filter</a>, which routes a run only to the team whose tests broke. It needs an <a href="./ai-diagnosis.html#scm-grounded-context">SCM token</a>; without one, ownership falls back to annotations alone.</p><h2 id="where-each-concept-lives-in-the-ui" tabindex="-1">Where each concept lives in the UI <a class="header-anchor" href="#where-each-concept-lives-in-the-ui" aria-label="Permalink to &quot;Where each concept lives in the UI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>URL</th><th>Docs</th></tr></thead><tbody><tr><td>Project</td><td><code>/projects/:id</code></td><td><a href="./ui-overview.html#project-detail">UI overview</a></td></tr><tr><td>Test run</td><td><code>/test-runs/:id</code></td><td><a href="./ui-overview.html#test-run-detail">UI overview</a></td></tr><tr><td>Test case</td><td><code>/test-cases/:id</code></td><td><a href="./ui-overview.html#test-case-detail">UI overview</a></td></tr><tr><td>Execution</td><td><code>/test-run-cases/:id</code></td><td><a href="./ui-overview.html#test-case-detail">UI overview</a></td></tr><tr><td>Failure cluster</td><td><code>/failure-clusters/:id</code></td><td><a href="./ai-diagnosis.html">AI diagnosis &amp; clustering</a></td></tr><tr><td>Cross-project view</td><td><code>/analytics</code></td><td><a href="./analytics.html">Analytics</a></td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./getting-started.html">Getting started</a> — get results flowing in</li><li><a href="./ui-overview.html">UI overview</a> — a map of every page</li><li><a href="./reporter.html">Reporter</a> — how each of these objects gets populated</li></ul>`,47)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
